const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');
function closeMenu(){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
document.querySelectorAll('[role="tablist"]').forEach(list=>{const tabs=[...list.querySelectorAll('[role="tab"]')];function select(tab){tabs.forEach(t=>{const on=t===tab;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;t.getAttribute('aria-controls').split(/\s+/).forEach(id=>{document.getElementById(id).hidden=!on;});});}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();select(tabs[n]);tabs[n].focus();}});});});
const timer=document.querySelector('.countdown');function tick(){let diff=new Date('2027-05-15T07:30:00+02:00').getTime()-Date.now();if(diff<=0){timer.textContent=Date.now()<new Date('2027-05-16T00:00:00+02:00').getTime()?timer.dataset.day:timer.dataset.ended;return;}let s=Math.floor(diff/1000);let values=[Math.floor(s/86400),Math.floor(s/3600)%24,Math.floor(s/60)%60,s%60];timer.querySelectorAll('[data-count]').forEach((el,i)=>el.textContent=String(values[i]).padStart(2,'0'));}tick();setInterval(tick,1000);
const checks=[...document.querySelectorAll('[data-check]')],checkKey='tip2027-preparations';let saved=[];try{saved=JSON.parse(localStorage.getItem(checkKey)||'[]');if(!Array.isArray(saved))saved=[];}catch{}
function checkProgress(){const p=document.querySelector('.check-progress');p.textContent=`${checks.filter(c=>c.checked).length} / ${checks.length} ${p.dataset.label}`;}
checks.forEach((c,i)=>{c.checked=saved.includes(i);c.addEventListener('change',()=>{try{localStorage.setItem(checkKey,JSON.stringify(checks.flatMap((c,i)=>c.checked?[i]:[])));}catch{}checkProgress();});});checkProgress();document.querySelector('.reset-checklist').addEventListener('click',()=>{checks.forEach(c=>c.checked=false);try{localStorage.removeItem(checkKey);}catch{}checkProgress();});
document.querySelectorAll('[data-color]').forEach(b=>b.addEventListener('click',()=>{const im=document.querySelector('#jersey');im.src=({magenta:'/assets/maillot-magenta.017dafd25935.webp',noir:'/assets/maillot-noir.155c9ba1a1b7.webp'})[b.dataset.color];im.alt=b.dataset.alt;document.querySelectorAll('[data-color]').forEach(c=>c.setAttribute('aria-pressed',String(c===b)));}));
const dialog=document.querySelector('#credits');document.querySelector('[data-open-dialog]').addEventListener('click',()=>dialog.showModal());document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const motion=document.querySelector('.motion-toggle');let paused=reduced.matches;function applyMotion(){document.body.classList.toggle('motion-paused',paused);motion.textContent=paused?motion.dataset.resume:motion.dataset.pause;motion.setAttribute('aria-pressed',String(paused));}applyMotion();motion.addEventListener('click',()=>{paused=!paused;applyMotion();});reduced.addEventListener('change',()=>{paused=reduced.matches;applyMotion();});
if('IntersectionObserver'in window&&!reduced.matches){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target);}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>{e.classList.add('will-reveal');io.observe(e);});}
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){nav.querySelectorAll('a').forEach(a=>{if(a.hash==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}});},{rootMargin:'-20% 0px -55% 0px'});document.querySelectorAll('#spirit,#event,#guide,#collector').forEach(s=>observer.observe(s));}
const photoViewer=document.querySelector('#photo-viewer'),photoButtons=[...document.querySelectorAll('[data-photo]')];
if(photoViewer){let photoIndex=0,photoTrigger=null;const full=photoViewer.querySelector('img'),caption=photoViewer.querySelector('.photo-caption');function showPhoto(i){photoIndex=(i+photoButtons.length)%photoButtons.length;const b=photoButtons[photoIndex];full.src=b.dataset.photo;full.alt=b.querySelector('img').alt;caption.textContent=`${photoIndex+1} / ${photoButtons.length}`;}photoButtons.forEach((b,i)=>b.addEventListener('click',()=>{photoTrigger=b;showPhoto(i);photoViewer.showModal();}));photoViewer.querySelector('.photo-close').addEventListener('click',()=>photoViewer.close());photoViewer.querySelector('.photo-prev').addEventListener('click',()=>showPhoto(photoIndex-1));photoViewer.querySelector('.photo-next').addEventListener('click',()=>showPhoto(photoIndex+1));photoViewer.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();showPhoto(photoIndex-1);}if(e.key==='ArrowRight'){e.preventDefault();showPhoto(photoIndex+1);}});photoViewer.addEventListener('close',()=>{full.removeAttribute('src');photoTrigger?.focus();});photoViewer.addEventListener('click',e=>{if(e.target===photoViewer){const r=photoViewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)photoViewer.close();}});}
